 const r={id:uid('re'),athlete:a.id,test:tid,session:'',value:h,date:today(),flight:Math.round(ft*1000),method:'Video',detect:vj.method||'manual',slow:vj.slow,fps:vj.fps,toF:vj.toF,ldF:vj.ldF,markTo:vj.toF/vj.fps,markLd:vj.ldF/vj.fps,t:Date.now()};db.results.push(r);save();
