async function vjClipShow(id){try{const b=await clipGet(id);if(!b){toast('Clip not found on this device');return}const r=db.results.find(x=>x.id===id)||{};modal(`<div class="row" style="justify-content:space-between"><b>${esc(nameOf(byId('athletes',r.athlete)))} · ${hTxt(+r.value)[0]}</b><button class="btn sm ghost" onclick="closeModal()">✕</button></div><video src="${URL.createObjectURL(b)}" controls playsinline style="margin-top:10px"></video><div class="muted" style="font-size:13px">Frames ${r.toF!=null?r.toF+1:'?'} → ${r.ldF!=null?r.ldF+1:'?'} @ ${r.fps} fps · ${r.flight} ms · ${r.detect||''}</div>`)}catch(e){toast('Clips are not available in this browser')}}
