function mlDel(id){confirmBox('Delete this report? Saved results stay.',()=>{db.mlReports=(db.mlReports||[]).filter(r=>r.id!==id);save();closeModal();render();toast('Report deleted')})}
function mlList(mode,aid){const L=(db.mlReports||[]).filter(r=>r.mode===mode&&(!aid||r.athlete===aid)).slice(0,8);if(!L.length)return `<p class="muted" style="margin:6px 0 0">No ${mode==='cmj'?'CMJ':'sprint'} reports yet.</p>`;
 return L.map(r=>{const b=r.reps[r.best]||{};return `<div class="item" style="cursor:pointer" onclick="mlReportView('${r.id}')"><span><b>${esc(nameOf(byId('athletes',r.athlete)))}</b> <span class="muted">${fmtDate(r.date)} · ${r.reps.length} ${mode==='cmj'?'jump':'rep'}(s) · ${esc(r.src)}</span></span><b>${mode==='cmj'?b.height+' cm':b.time+' s'} ›</b></div>`}).join('')}
/* inject on the Video Jump and Speed Log pages */
function mlInject(p){const v=document.getElementById('view');if(!v)return;
 if(p==='video-jump'){if(vj.url){if(vj.lm&&vj.lm.some(Boolean)&&!document.getElementById('mlVidRep')){const m=document.getElementById('vjMsg');if(m)m.insertAdjacentHTML('afterend',`<button id="mlVidRep" class="btn pri" style="margin:6px 0" onclick="mlFromVideo()">📊 Full CMJ report from this video</button>`)}return}
  const a=byId('athletes',vj.ath);const first=v.querySelector('.card');if(!first)return;
  first.insertAdjacentHTML('beforebegin',`<div class="card mlcard"><div class="row" style="justify-content:space-between"><div><h3 style="margin:0">🎥 Live CMJ with body tracking</h3><p class="muted" style="margin:4px 0 0">Point the camera, the skeleton follows the athlete in real time, every jump is measured automatically and you get a full CMJ report.</p></div>
  <span class="row"><button class="btn" onclick="btCheck()">🦴 Check body tracking</button><button class="btn pri" style="font-size:18px;padding:14px 22px" onclick="mlOpen('cmj')">● Start live CMJ${a?' — '+esc(a.name.split(' ')[0]):''}</button></span></div><h4 style="margin:14px 0 4px">CMJ reports${a?' — '+esc(a.name):''}</h4>${mlList('cmj',a&&a.id)}</div>`)}
 if(p==='speed-log'){const a=byId('athletes',sl.ath);const first=v.querySelector('.card');if(first&&!document.getElementById('mlSpCard'))first.insertAdjacentHTML('beforebegin',`<div class="card mlcard" id="mlSpCard"><div class="row" style="justify-content:space-between"><div><h3 style="margin:0">🎥 Live sprint with body tracking</h3><p class="muted" style="margin:4px 0 0">Camera side-on to the lane: the skeleton tracks the runner, the time starts and stops on your gates, and steps, step rate, lean and knee drive go into a sprint report.</p></div>
  <span class="row"><button class="btn" onclick="btCheck()">🦴 Check body tracking</button><button class="btn pri" style="font-size:18px;padding:14px 22px" onclick="mlOpen('sprint')">● Start live sprint${a?' — '+esc(a.name.split(' ')[0]):''}</button></span></div><h4 style="margin:14px 0 4px">Sprint reports${a?' — '+esc(a.name):''}</h4>${mlList('sprint',a&&a.id)}</div>`);
  const sv=document.getElementById('spVid');if(sv&&!document.getElementById('spPoseC')){const w=document.createElement('div');w.className='vjwrap';w.style.marginTop='14px';sv.style.marginTop='0';sv.parentNode.insertBefore(w,sv);w.appendChild(sv);w.insertAdjacentHTML('beforeend','<canvas id="spPoseC"></canvas>');
   w.insertAdjacentHTML('afterend',`<label class="row" style="gap:8px;margin:8px 0"><input type="checkbox" style="width:auto" ${ML.spPose?'checked':''} onchange="ML.spPose=this.checked;spPoseTick(true)"> 🦴 Skeleton overlay (2D pose + joint angles)</label>`);
   ['seeked','pause','loadeddata'].forEach(e=>sv.addEventListener(e,()=>spPoseTick(true)));sv.addEventListener('play',()=>spPoseTick(true));if(ML.spPose)setTimeout(()=>spPoseTick(true),300)}}}
async function spPoseTick(force){const v=document.getElementById('spVid'),c=document.getElementById('spPoseC');if(!v||!c)return;const x=c.getContext('2d');const W=v.clientWidth,H=v.clientHeight;c.width=W;c.height=H;x.clearRect(0,0,W,H);if(!ML.spPose||!v.videoWidth)return;
 if(spPoseTick.busy)return;spPoseTick.busy=true;try{const P=await btGet('player',1,false);const lm=mlNorm(await P.send(v));x.clearRect(0,0,W,H);mlDraw(x,lm,mlBox(v,W,H),{angles:true})}catch(e){toast('Body tracking could not load here');ML.spPose=false}spPoseTick.busy=false;if(ML.spPose&&!v.paused)requestAnimationFrame(()=>spPoseTick())}
function mlFromVideo(){if(!vj.lm){toast('Run detection first');return}const v=document.getElementById('vjV');const a=byId('athletes',vj.ath);if(!a){toast('Pick the athlete first');return}
 const fr=vj.lm.map((lm,i)=>({t:i/vj.fps/vj.slow,lm}));const o={heightCm:+a.height,mass:mlMass(a.id),ar:v&&v.videoWidth?v.videoWidth/v.videoHeight:9/16};if(vj.toF!=null&&vj.ldF!=null){o.toT=vj.toF/vj.fps/vj.slow;o.ldT=vj.ldF/vj.fps/vj.slow}
 const r=cmjAnalyze(fr,o);if(!r){toast('Could not find a clean jump in the tracked frames');return}r.at=new Date().toISOString();r.fps=Math.round(vj.fps*vj.slow);
 const snaps={};const can=document.createElement('canvas');const grab=async(k,i)=>{if(!v)return;await new Promise(res=>{v.onseeked=()=>res();v.currentTime=i/vj.fps+0.001;setTimeout(res,800)});const w=360,h=Math.round(w*v.videoHeight/v.videoWidth);can.width=w;can.height=h;const x=can.getContext('2d');x.drawImage(v,0,0,w,h);mlDraw(x,vj.lm[i],{ox:0,oy:0,dw:w,dh:h,ar:v.videoWidth/v.videoHeight},{s:.7});snaps[k]=can.toDataURL('image/jpeg',.72)};
 (async()=>{for(const [k,i] of [['low',r.iLow],['take',r.iTo],['peak',r.iPk],['land',Math.min(vj.lm.length-1,r.iLd)]])await grab(k,i);r.snaps=snaps;mlSaveReport('cmj',a.id,[r],'Recorded video',vj.file||null)})()}

/* Import */
function parseCSV(t){const rows=[];let row=[],cur='',q=false;for(let i=0;i<t.length;i++){const ch=t[i];
 if(q){if(ch==='"'&&t[i+1]==='"'){cur+='"';i++}else if(ch==='"')q=false;else cur+=ch}
 else if(ch==='"')q=true;else if(ch===','){row.push(cur);cur=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&t[i+1]==='\n')i++;row.push(cur);rows.push(row);row=[];cur=''}else cur+=ch}
 if(cur||row.length){row.push(cur);rows.push(row)}return rows.filter(r=>r.some(x=>x.trim()))}
