 const para=(s,o={})=>{const z=o.z||10,f=o.f||F,lh=z*1.45;wrap(s,f,z,o.w||CW).forEach(l=>{need(lh);T(l,o.x||M,y,{f,z,c:o.c});y-=lh});y-=o.gap??4};
