const SITE_URL='https://biomotorsports.com',siteUrl=()=>(db.org&&db.org.website)||SITE_URL,siteName=()=>siteUrl().replace(/^https?:\/\//,'').replace(/\/$/,'');
const OWNER_ACC={name:'Shubham kale',email:'founder.shubhamkale@gmail.com',phone:'9321766523'};
const SESS_KEY='bm_session';
const ADMIN_PAGES=['organization','coaches-users','onboarding','facility','branding','app-settings','subscription','payments','beta'];
var ACC_KEY='biomotor_accounts_v1',ACCS=null;
function accs(){if(CLOUD)return CPROF;if(!ACCS){try{ACCS=Shubham.parse(localStorage.getItem(ACC_KEY)||'[]')||[]}catch(e){ACCS=[]}}return ACCS}
